"""Display widgets — widgets that present content."""

from __future__ import annotations

from typing import Any, Callable, Literal

from workpeg.ui.state import Binding
from workpeg.ui.widgets.base import BaseWidget, WidgetChild


class Text(BaseWidget):
    widget_type = "Text"

    def __init__(
        self,
        value: str | int | float | Binding,
        *,
        variant: Literal[
            "display",
            "title",
            "heading",
            "subheading",
            "body",
            "caption",
            "label",
            "muted",
            "code",
        ] = "body",
        tone: Literal[
            "default",
            "muted",
            "success",
            "warning",
            "danger",
            "info",
        ] = "default",
        weight: Literal[
            "regular",
            "medium",
            "semibold",
            "bold",
        ] = "regular",
        key: str | None = None,
        visible: bool | Binding = True,
        disabled: bool | Binding = False,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key,
            visible=visible,
            disabled=disabled,
            metadata=metadata,
        )
        self.value = value
        self.variant = variant
        self.tone = tone
        self.weight = weight

    def props(self) -> dict[str, Any]:
        return {
            "value": self.value,
            "variant": self.variant,
            "tone": self.tone,
            "weight": self.weight,
        }


class Locale(BaseWidget):
    """A translated string — resolved to the active language at render time.

    Looks ``token`` up in the Peg's :class:`~workpeg.ui.Translations` catalogue::

        Locale("greeting")                              # "Hello" / "Bonjour"
        Locale("greeting", values={"name": self.name})  # fills {name}
        Locale("greeting", fallback="Hello")             # if the token is missing

    Resolution order for a token: the active language, then the catalogue's
    ``default`` language, then ``fallback``, then the token itself — so a missing
    translation degrades to something readable rather than a blank. The active
    language follows the user's workspace choice; switching it re-renders every
    ``Locale`` in place.

    The message is set with ``textContent`` — never ``innerHTML`` — so a
    catalogue entry can never inject markup. ``variant`` styles it on the same
    typography ladder as :class:`Text`.
    """

    widget_type = "Locale"

    def __init__(
        self,
        token: str | Binding,
        *,
        fallback: str = "",
        values: dict[str, Any] | None = None,
        variant: Literal[
            "display", "title", "heading", "subheading", "body",
            "caption", "label", "muted", "code",
        ] = "body",
        key: str | None = None,
        visible: bool | Binding = True,
        disabled: bool | Binding = False,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key, visible=visible, disabled=disabled, metadata=metadata,
        )
        # `token` first, NOT `key` — `key` is reserved by BaseWidget.
        self.token = token
        self.fallback = fallback
        self.values = values or {}
        self.variant = variant

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {"token": self.token, "variant": self.variant}
        if self.fallback:
            p["fallback"] = self.fallback
        if self.values:
            p["values"] = self.values
        return p


class Image(BaseWidget):
    """An image, rendered as an ``<img>`` element.

    Inspired by Flutter's ``Image``: a *src* URL plus optional sizing and a
    ``fit`` that maps to CSS ``object-fit`` (the analogue of ``BoxFit``).

    Best practices are baked in: ``alt`` text is always emitted for
    accessibility, images are lazy-loaded and decoded asynchronously by
    default, and the element is ``display: block`` to avoid inline gaps.

    Compiler API::

        Image("https://example.com/cat.jpg", width=240, height=160)
        Image("/avatar.png", width=48, height=48, radius=24, alt="You")
        Image(f"/photos/{self.id}.jpg", fit="contain", alt="Photo")

    ``fit`` is one of ``"cover"`` (default), ``"contain"``, ``"fill"``,
    ``"none"``, or ``"scale_down"``.

    A picture that fails to load (or whose URL the scheme check refuses)
    leaves a blank box: the ``width``/``height`` given are kept, a dimension
    not given is 0 (the size of an image still loading), nothing is drawn
    in it in any browser, and ``alt`` stays on the element. The URL is not
    requested again for ten seconds, however often the page re-renders, and
    is after that, so a picture that failed for a moment shows on the next
    render; a flag that failed in a ``Dropdown`` stays failed for the page.
    """

    widget_type = "Image"

    def __init__(
        self,
        src: str | Binding,
        *,
        width: int | str | None = None,
        height: int | str | None = None,
        fit: Literal[
            "cover",
            "contain",
            "fill",
            "none",
            "scale_down",
        ] = "cover",
        alt: str | Binding = "",
        radius: int | str | None = None,
        lazy: bool = True,
        key: str | None = None,
        visible: bool | Binding = True,
        disabled: bool | Binding = False,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key,
            visible=visible,
            disabled=disabled,
            metadata=metadata,
        )
        self.src = src
        self.width = width
        self.height = height
        self.fit = fit
        self.alt = alt
        self.radius = radius
        self.lazy = lazy

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {
            "src": self.src,
            "alt": self.alt,
            "fit": self.fit,
            "lazy": self.lazy,
        }
        if self.width is not None:
            p["width"] = self.width
        if self.height is not None:
            p["height"] = self.height
        if self.radius is not None:
            p["radius"] = self.radius
        return p


class Logo(BaseWidget):
    """The Peg's brand logo from the Workpeg CDN — you never pass a URL, it's
    built for you.

    The Peg ``namespace`` is resolved automatically from the serving host
    (``*.<namespace>.workpeg.com``, then the ``peg-namespace`` ``<meta>`` baked
    into the page) — the *same* namespace ``workpeg.*`` sends as its header. It's
    never passed in, so a Logo always shows the current Peg's own brand. The CDN
    path is ``/pegs/<namespace>/assets/logo/<variant>-<theme>.svg``::

        Logo()                                   # this Peg, primary, auto theme
        Logo(variant="secondary", height=22)     # the secondary mark
        Logo(theme="dark")                        # force the dark-background art

    ``variant`` is ``"primary"`` (default) or ``"secondary"``. ``theme`` is
    ``"automatic"`` (default — follows the OS via ``prefers-color-scheme``,
    swapping the light/dark art live), ``"light"``, or ``"dark"``.

    Every :class:`Image` attribute *except* ``src`` is accepted
    (``width`` / ``height`` / ``alt`` / ``fit`` / ``radius`` / ``lazy``, plus
    ``style``). ``fit`` defaults to ``"contain"`` so the mark is never cropped.
    If the logo hasn't been uploaded (the file fails to load), the image is
    simply **hidden** — no broken-image marker, no warning.
    """

    widget_type = "Logo"

    def __init__(
        self,
        *,
        variant: Literal["primary", "secondary"] = "primary",
        theme: Literal["light", "dark", "automatic"] = "automatic",
        width: int | str | None = None,
        height: int | str | None = None,
        fit: Literal[
            "cover", "contain", "fill", "none", "scale_down"
        ] = "contain",
        alt: str | Binding = "",
        radius: int | str | None = None,
        lazy: bool = True,
        key: str | None = None,
        visible: bool | Binding = True,
        disabled: bool | Binding = False,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key,
            visible=visible,
            disabled=disabled,
            metadata=metadata,
        )
        self.variant = variant
        self.theme = theme
        self.width = width
        self.height = height
        self.fit = fit
        self.alt = alt
        self.radius = radius
        self.lazy = lazy

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {
            "variant": self.variant,
            "theme": self.theme,
            "alt": self.alt,
            "fit": self.fit,
            "lazy": self.lazy,
        }
        if self.width is not None:
            p["width"] = self.width
        if self.height is not None:
            p["height"] = self.height
        if self.radius is not None:
            p["radius"] = self.radius
        return p


class GravatarImage(BaseWidget):
    """An avatar that resolves an email to its `Gravatar <https://gravatar.com>`_,
    falling back to a coloured initials tile when none exists.

    It carries the same image attributes as :class:`Image` (``width``,
    ``height``, ``fit``, ``radius``, ``alt``) and adds the avatar bits: the
    ``email`` to look up, the ``initials`` to show if there's no Gravatar, and
    the ``bg`` / ``color`` of that fallback tile. The initials render
    immediately; the Gravatar overlays them once it loads, and a missing one
    (Gravatar returns 404) just leaves the initials in place — so there's never
    a broken-image flash. Circular by default (override ``radius``)::

        GravatarImage(user.email, initials="TA", width=40)
        GravatarImage(self.email, initials=self.initials,
                      bg="#5b6472", color="#ffffff", width=64, radius=8)

    The email is hashed in the browser (MD5, per the Gravatar spec); pass it
    dynamically (``user.email``, an f-string, state). ``initials`` is plain text
    set via ``textContent`` — never markup.
    """

    widget_type = "GravatarImage"

    def __init__(
        self,
        email: str | Binding,
        *,
        initials: str | Binding = "",
        bg: str | Binding = "#dce1ea",
        color: str | Binding = "#1b2333",
        width: int | str = 40,
        height: int | str | None = None,
        fit: Literal[
            "cover",
            "contain",
            "fill",
            "none",
            "scale_down",
        ] = "cover",
        alt: str | Binding = "",
        radius: int | str | None = None,
        key: str | None = None,
        visible: bool | Binding = True,
        disabled: bool | Binding = False,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key,
            visible=visible,
            disabled=disabled,
            metadata=metadata,
        )
        self.email = email
        self.initials = initials
        self.bg = bg
        self.color = color
        self.width = width
        self.height = height
        self.fit = fit
        self.alt = alt
        self.radius = radius


class CameraView(BaseWidget):
    """A live camera preview, rendered as a muted, inline ``<video>``.

    Opens the device camera (``getUserMedia``) and shows it. The stream is
    acquired **once per page** (cached on the app), so a re-render rebinds the
    element instead of re-prompting; navigating away stops the camera::

        CameraView(width=320, height=240, on_error=self.denied)
        CameraView(facing="environment", radius=12)   # rear camera, rounded

    ``facing`` is ``"user"`` (front, default) or ``"environment"`` (rear);
    ``audio`` also captures the mic (off by default — preview is silent).
    ``on_error`` is a ``self.method`` called (with a message) if the camera is
    unavailable or the user denies it. Sizing mirrors :class:`Image`
    (``width`` / ``height`` / ``fit`` / ``radius``). Needs HTTPS.
    """

    widget_type = "CameraView"

    def __init__(
        self,
        *,
        facing: Literal["user", "environment"] = "user",
        audio: bool = False,
        label: str | Binding = "Start camera",
        width: int | str | None = None,
        height: int | str | None = None,
        fit: Literal["cover", "contain", "fill", "none", "scale_down"] = "cover",
        radius: int | str | None = None,
        on_error: Callable | None = None,
        key: str | None = None,
        visible: bool | Binding = True,
        disabled: bool | Binding = False,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(key=key, visible=visible, disabled=disabled,
                         metadata=metadata)
        self.facing = facing
        self.audio = audio
        self.label = label
        self.width = width
        self.height = height
        self.fit = fit
        self.radius = radius
        self.on_error = on_error


class ScreenShare(BaseWidget):
    """A live screen-share preview, rendered as a muted, inline ``<video>``.

    Opens a screen / window / tab capture (``getDisplayMedia``) and shows it. Like
    :class:`CameraView`, the stream is acquired once per page and stopped on
    navigation::

        ScreenShare(width=480, on_end=self.stopped, on_error=self.denied)

    ``on_end`` is a ``self.method`` called when the user stops sharing (via the
    browser's own control); ``on_error`` fires if capture is unavailable or
    denied. Sizing mirrors :class:`Image`. Needs HTTPS, and the browser always
    prompts which surface to share.
    """

    widget_type = "ScreenShare"

    def __init__(
        self,
        *,
        label: str | Binding = "Share screen",
        width: int | str | None = None,
        height: int | str | None = None,
        fit: Literal["cover", "contain", "fill", "none", "scale_down"] = "contain",
        radius: int | str | None = None,
        on_end: Callable | None = None,
        on_error: Callable | None = None,
        key: str | None = None,
        visible: bool | Binding = True,
        disabled: bool | Binding = False,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(key=key, visible=visible, disabled=disabled,
                         metadata=metadata)
        self.label = label
        self.width = width
        self.height = height
        self.fit = fit
        self.radius = radius
        self.on_end = on_end
        self.on_error = on_error


class FileUpload(BaseWidget):
    """A file picker with a built-in preview — Flutter's ``FilePicker`` plus the
    drop zone.

    Renders a click-or-drop zone wrapping a hidden ``<input type="file">``. When
    files are chosen (via the picker or drag-and-drop) it calls
    ``on_select(files)`` with a list of ``{"name", "size", "type", "url"}`` dicts:
    ``url`` is a local ``blob:`` object URL — safe to use as an :class:`Image`
    ``src`` or to upload (it's revoked automatically when you navigate away). With
    ``preview=True`` (the default) it also renders thumbnails itself — images as a
    picture, anything else as a name + size card — so a preview needs no wiring::

        FileUpload(on_select=self.chose, accept="image/*", multiple=True)
        FileUpload(on_select=self.chose, max_size=5, on_error=self.too_big)
        FileUpload(on_select=self.chose, preview=False, label="Attach a file")

    ``accept`` is the standard filter (``"image/*"``, ``".pdf,.png"``);
    ``multiple`` allows several files; ``max_size`` (in MB) rejects larger files
    and fires ``on_error(message)``. The file name renders via ``textContent`` —
    never markup — so it can't inject. Nothing is read or uploaded for you; the
    handler decides what to do with the selection.
    """

    widget_type = "FileUpload"

    def __init__(
        self,
        *,
        on_select: Callable | None = None,
        on_error: Callable | None = None,
        accept: str | None = None,
        multiple: bool = False,
        max_size: int | float | None = None,
        preview: bool = True,
        label: str | Binding = "Choose a file or drop it here",
        height: int | str | None = None,
        radius: int | str | None = None,
        disabled: bool | Binding = False,
        key: str | None = None,
        visible: bool | Binding = True,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key, visible=visible, disabled=disabled, metadata=metadata,
        )
        self.on_select = on_select
        self.on_error = on_error
        self.accept = accept
        self.multiple = multiple
        self.max_size = max_size
        self.preview = preview
        self.label = label
        self.height = height
        self.radius = radius


#: Video's src_object when it is not given, so ``src_object=None`` (a stream
#: that has not arrived yet) is a value of its own.
_NO_STREAM = object()


class Video(BaseWidget):
    """A video player, rendered as a ``<video>`` element.

    Like :class:`Image`, but for video: a *src* URL plus playback flags. ``src``
    and ``poster`` (a placeholder image) may be dynamic (state / f-strings);
    sizing is constant. ``autoplay`` implies muted, inline playback (the only way
    browsers allow it). The element is ``display: block`` and caps at the
    container width::

        Video("/clip.mp4", width=480, controls=True)
        Video(f"/lessons/{self.id}.mp4", poster="/thumb.jpg", controls=True)
        Video("/bg.mp4", autoplay=True, loop=True, muted=True)   # silent loop

    Or a live stream: ``src_object`` is a stream handle from
    :mod:`workpeg.ui.rtc` (what ``media_devices.get_user_media`` gives, or a
    call's remote stream), in place of ``src``. It plays at once and inline,
    with no controls unless asked, and ``None`` draws an empty element, so
    a page can lay out a call before its stream arrives. The page keeps the
    element by its stream, so neither a state write nor another view
    appearing or going beside it (a self-view, a participant leaving a grid)
    restarts the call. A stream video takes ``muted``, ``controls`` and the
    sizing; ``poster``, ``autoplay`` and ``loop`` are a URL's::

        Video(src_object=self.local, muted=True, width=160)   # your camera
        Video(src_object=self.remote, width=480)              # the other side

    Exactly one of ``src`` and ``src_object`` is given.
    """

    widget_type = "Video"

    def __init__(
        self,
        src: str | Binding | None = None,
        *,
        src_object: Any = _NO_STREAM,
        width: int | str | None = None,
        height: int | str | None = None,
        controls: bool | None = None,
        autoplay: bool = False,
        loop: bool = False,
        muted: bool = False,
        poster: str | Binding | None = None,
        radius: int | str | None = None,
        key: str | None = None,
        visible: bool | Binding = True,
        disabled: bool | Binding = False,
        metadata: dict[str, Any] | None = None,
    ):
        stream = src_object is not _NO_STREAM
        if (src is None) == (not stream):
            raise TypeError(
                "Video() takes src, a URL to play, or src_object, a stream "
                "handle such as get_user_media gives: exactly one of them")
        if stream and (poster is not None or autoplay or loop):
            raise TypeError(
                "Video(src_object=) plays a stream at once: poster, autoplay "
                "and loop are for a URL in src")
        super().__init__(
            key=key, visible=visible, disabled=disabled, metadata=metadata,
        )
        self.src = src
        self.src_object = src_object if stream else None
        self.width = width
        self.height = height
        self.controls = (not stream) if controls is None else controls
        self.autoplay = autoplay
        self.loop = loop
        self.muted = muted
        self.poster = poster
        self.radius = radius

    def props(self) -> dict[str, Any]:
        if self.src is None:
            p: dict[str, Any] = {"src_object": self.src_object,
                                 "controls": self.controls,
                                 "muted": self.muted}
        else:
            p = {
                "src": self.src,
                "controls": self.controls,
                "autoplay": self.autoplay,
                "loop": self.loop,
                "muted": self.muted,
            }
        for name in ("width", "height", "radius", "poster"):
            value = getattr(self, name)
            if value is not None:
                p[name] = value
        return p


class Audio(BaseWidget):
    """A stream's sound, played by an ``<audio autoplay>`` with no controls.

    ``src_object`` is a stream handle from :mod:`workpeg.ui.rtc`, usually a
    call's remote stream; ``None`` plays nothing. Nothing is drawn: the page
    keeps the element across renders, so a state write does not interrupt
    the call. To show a stream's video as well, a :class:`Video` of the same
    stream is its own element; mute one of them so the sound plays once::

        Audio(src_object=self.remote)
    """

    widget_type = "Audio"

    def __init__(
        self,
        *,
        src_object: Any,
        key: str | None = None,
        visible: bool | Binding = True,
    ):
        super().__init__(key=key, visible=visible)
        self.src_object = src_object

    def props(self) -> dict[str, Any]:
        return {"src_object": self.src_object}


class FileView(BaseWidget):
    """Show the **contents** of an uploaded file — text, or a hex dump for
    binaries — in a scrollable monospace pane.

    ``src`` is the file URL, usually the object URL a :class:`FileUpload` hands
    back for the user's *own* file (a ``blob:`` URL, allowed here even though
    links reject it); it may be dynamic (state / f-string). ``mode`` is
    ``"auto"`` (sniff text vs binary), ``"text"`` (decode UTF-8) or ``"hex"`` (a
    classic offset/hex/ASCII dump); ``height`` caps the pane (it scrolls),
    ``max_bytes`` caps how much is read. The runtime fetches the same-origin
    blob, re-checks the URL scheme (``blob:``/``http(s)``/relative), and shows
    the result as plain text (``textContent``) — never HTML, so nothing in the
    file can inject::

        # show whatever the user uploaded
        FileView(self.file_url, height=400)        # auto text/hex
        FileView(self.file_url, mode="hex")        # force a hex dump
    """

    widget_type = "FileView"

    def __init__(
        self,
        src: str | Binding,
        *,
        mode: str = "auto",
        height: int = 360,
        max_bytes: int = 262144,
        radius: int | None = None,
        key: str | None = None,
        visible: bool | Binding = True,
        disabled: bool | Binding = False,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key, visible=visible, disabled=disabled, metadata=metadata,
        )
        self.src = src
        self.mode = mode
        self.height = height
        self.max_bytes = max_bytes
        self.radius = radius

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {
            "src": self.src, "mode": self.mode,
            "height": self.height, "max_bytes": self.max_bytes,
        }
        if self.radius is not None:
            p["radius"] = self.radius
        return p


class Code(BaseWidget):
    """Source code or preformatted text, shown verbatim in a monospace font.

    A block (default) is a scrolling ``<pre><code>`` that preserves whitespace
    and newlines; ``inline=True`` is an inline ``<code>`` span. The text may be
    dynamic, and is set as ``textContent`` — shown literally, never parsed as
    HTML — so it can't inject markup or scripts::

        Code("def hello():\\n    return 'hi'")          # a code block
        Code(f"npm install {self.pkg}", inline=True)    # inline snippet
        Code(self.snippet, copyable=True)               # with a copy button

    ``copyable=True`` puts a copy button in the block's corner. It needs no
    handler: the widget already holds the text, and asking for one would mean
    writing the snippet down twice and letting the two drift. The button
    reports itself for two seconds after a copy, because a clipboard write is
    otherwise completely silent. Ignored for ``inline=True`` — there is no
    corner to put it in.
    """

    widget_type = "Code"

    def __init__(
        self,
        text: str | Binding,
        *,
        inline: bool = False,
        copyable: bool = False,
        key: str | None = None,
        visible: bool | Binding = True,
        disabled: bool | Binding = False,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key, visible=visible, disabled=disabled, metadata=metadata,
        )
        self.text = text
        self.inline = inline
        self.copyable = copyable

    def props(self) -> dict[str, Any]:
        return {"value": self.text, "inline": self.inline}


class Markdown(BaseWidget):
    """Render Markdown text as formatted content — **safely**.

    The runtime parses the Markdown and builds the result from real DOM nodes
    (``createElement`` + ``textContent``); it never uses ``innerHTML``, so the
    text can't inject markup or scripts. Raw HTML in the source is shown as
    literal text, and link URLs are sanitised (``javascript:`` / ``data:`` and
    other schemes are dropped). The supported subset covers chat messages:
    headings, bold / italic, inline code and fenced code blocks, links, blockquotes,
    and ordered / unordered lists. ``text`` may be dynamic::

        Markdown("**Hi!** Run `pip install workpeg` — see [docs](/docs).")
        Markdown(self.message)          # reactive
    """

    widget_type = "Markdown"

    def __init__(
        self,
        text: str | Binding,
        *,
        key: str | None = None,
        visible: bool | Binding = True,
        disabled: bool | Binding = False,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key, visible=visible, disabled=disabled, metadata=metadata,
        )
        self.text = text

    def props(self) -> dict[str, Any]:
        return {"value": self.text}


class HtmlView(BaseWidget):
    """Render an **untrusted** HTML + CSS document safely — e.g. an email body.

    Unlike :class:`Markdown` (which renders a small markup *language* and shows
    raw HTML as literal text), ``HtmlView`` parses real HTML — tables, inline
    ``style=``, ``bgcolor``, ``<font>``, and ``<style>`` blocks — and renders it.
    It **never runs JavaScript of any kind**: the document is rebuilt node by
    node from a tag/attribute allowlist (``createElement`` + ``textContent``,
    never ``innerHTML``), so ``<script>``, ``on*=`` handlers,
    ``javascript:`` / ``data:text/html`` URLs and CSS ``expression()`` / ``url()``
    are all dropped. CSS inside ``<style>`` blocks is sanitised and **scoped to
    this view**, so an email's styles can't leak out and restyle your app::

        HtmlView(self.email_html)              # reactive — re-renders on change
        HtmlView("<h1>Hi</h1><p>See <a href='https://x.com'>this</a>.</p>")

    Images render via ``<img>`` (http(s) or ``data:image`` only); links open in a
    new tab with ``rel=noopener``. The ``html`` may be dynamic (state / f-string).
    """

    widget_type = "HtmlView"

    def __init__(
        self,
        html: str | Binding,
        *,
        key: str | None = None,
        visible: bool | Binding = True,
        disabled: bool | Binding = False,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key, visible=visible, disabled=disabled, metadata=metadata,
        )
        self.html = html

    def props(self) -> dict[str, Any]:
        return {"value": self.html}


class Icon(BaseWidget):
    """A vector icon from the Pegment icon set (Tabler Icons) —
    `browse them <https://design.workpeg.com/icons.html>`_.

    Rendered as an ``<i class="ti ti-<name>">`` styled by the icon stylesheet:
    it draws with the current text ``color`` (so it inherits its surroundings)
    and sizes to ``1em`` by default, so an icon next to text just works::

        Icon("home")
        Icon("settings", size=20)
        Icon("alert-triangle", size=24, color="#e23b3b")
        Icon("heart-filled", color="#e23b3b")   # filled variant
        Row(Icon("search"), Text("Search"), gap=6)

    ``name`` is the Tabler name without the ``ti-`` prefix (``"arrow-left"``,
    ``"brand-github"``); append ``-filled`` for an icon's filled variant
    (``"heart-filled"``). ``size`` is the box in px (sets ``--icon-size``);
    ``color`` overrides the inherited colour; ``weight`` picks the stroke
    width — unspecified renders the **2px default**, ``"thin"`` (or ``1.5``)
    is the lighter outline, ``"bolder"`` (or ``2.5``) the heaviest, and a
    numeric ``1`` keeps the raw 1px Tabler mask.
    The weight can also ride in the name as a suffix
    (``"shield-lock:thin"``, ``"shield-lock:bolder"``), which wins over the
    parameter. The stylesheet is loaded from ``cdn.workpeg.com`` and only
    when a build actually uses an icon.
    """

    widget_type = "Icon"

    def __init__(
        self,
        name: str,
        *,
        size: int | str | None = None,
        color: str | Binding | None = None,
        weight: int | float | str | None = None,
        key: str | None = None,
        visible: bool | Binding = True,
        disabled: bool | Binding = False,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key, visible=visible, disabled=disabled, metadata=metadata,
        )
        self.name = name
        self.size = size
        self.color = color
        self.weight = weight

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {"name": self.name}
        if self.size is not None:
            p["size"] = self.size
        if self.color is not None:
            p["color"] = self.color
        if self.weight is not None:
            p["weight"] = str(self.weight)
        return p


class Dot(BaseWidget):
    """A small filled circle — a status or "live" marker, the shape the
    design system draws in a toggle (``.tgl-btn__dot``) and a button
    (``Button(dot=True)``)::

        ToggleButton(Dot(), Text("Live"), ...)
        Row(Dot(color="var(--color-success-500)"), Text("Online"), gap=6)

    8px and drawn in ``currentColor`` by default, so it takes the colour of
    whatever it sits in — a selected toggle's blue, a muted label's grey.
    ``color`` overrides that; a literal is checked against the same CSS
    value deny-list as every style value, and a dynamic one again at
    runtime. ``style=`` can resize it. Decorative: screen readers skip it,
    so say in text what it means.
    """

    widget_type = "Dot"

    def __init__(
        self,
        *,
        color: str | Binding | None = None,
        key: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, **kwargs)
        self.color = color

    def props(self) -> dict[str, Any]:
        return {"color": self.color} if self.color is not None else {}


class Spinner(BaseWidget):
    """An indeterminate loading spinner — Flutter's ``CircularProgressIndicator``.
    A spinning ring, animated purely in CSS (no JS), with no content of its own.
    ``size`` is the diameter in px::

        Spinner()            # 24px
        Spinner(size=40)
    """

    widget_type = "Spinner"

    def __init__(
        self,
        *,
        size: int = 24,
        key: str | None = None,
        visible: bool | Binding = True,
        disabled: bool | Binding = False,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key, visible=visible, disabled=disabled, metadata=metadata,
        )
        self.size = size

    def props(self) -> dict[str, Any]:
        return {"size": self.size}


class Progress(BaseWidget):
    """A linear progress bar — Flutter's ``LinearProgressIndicator``. Pass
    ``value`` (``0.0``–``1.0``, may be dynamic) for a determinate bar; omit it
    for the indeterminate animated bar. The value is coerced to a number and
    clamped in the runtime, then written via the CSSOM — never a style string —
    so it can't inject CSS::

        Progress(value=0.4)          # 40%
        Progress(value=self.ratio)   # reactive
        Progress()                   # indeterminate
    """

    widget_type = "Progress"

    def __init__(
        self,
        *,
        value: float | Binding | None = None,
        key: str | None = None,
        visible: bool | Binding = True,
        disabled: bool | Binding = False,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key, visible=visible, disabled=disabled, metadata=metadata,
        )
        self.value = value

    def props(self) -> dict[str, Any]:
        return {"value": self.value}


class Badge(BaseWidget):
    """A small count / status indicator — Flutter's ``Badge``. Standalone (a
    pill), or anchored to a ``child`` (floated at its top-right); with no
    ``label`` it's a dot::

        Badge("3")
        Badge("9+", child=Button("Inbox", on_click=self.open))
        Badge(child=Text("●"))     # a dot

    The label may be dynamic and is set with ``textContent`` — never
    ``innerHTML`` — so it can't inject markup.
    """

    widget_type = "Badge"

    def __init__(
        self,
        label: str | Binding | None = None,
        *,
        child: WidgetChild | None = None,
        key: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, **kwargs)
        self.label = label
        self.child = child

    def children(self) -> list[WidgetChild]:
        return [self.child] if self.child is not None else []

    def props(self) -> dict[str, Any]:
        return {"label": self.label}


#: The thirteen tones `.badge--<tone>` defines in pegment.css.
TAG_TONES = (
    "neutral", "neutral-bold", "neutral-text", "critical", "critical-bold",
    "warning", "success", "info", "accent", "purple", "pink", "rose",
    "orange",
)

#: `fill="filled"` is defined for these five only. The design hand-picks each
#: background/text pair (critical goes white on solid red, warning stays dark
#: on amber) rather than deriving it, and specifies no filled treatment for
#: the other eight — so those are refused by name instead of silently
#: rendering the subtle style, which would read as the argument being
#: ignored. `outline` needs no such list: it is derivable for every tone.
TAG_FILLED_TONES = ("neutral", "critical", "warning", "success", "accent")

#: `size="md"` is the base rule and emits no class of its own.
TAG_SIZES = ("sm", "md", "lg")

TAG_FILLS = ("subtle", "filled", "outline")

#: Preset name -> the arguments it fixes. Read by the compiler too, so the
#: Python and the parser cannot drift.
TAG_PRESETS: dict[str, dict[str, Any]] = {
    "FilledTag": {"fill": "filled"},
    "OutlineTag": {"fill": "outline"},
}


class Tag(BaseWidget):
    """A status pill — the design system's badge (``badges.html``).

    Named ``Tag`` because :class:`Badge` in this SDK is already Flutter's
    anchored counter, which is a different object; this one emits the
    design's own ``.badge`` classes::

        Tag("Label", tone="critical", size="sm")
        Tag("New", tone="info", arrow=True)
        Tag("draft", dot=True)

    **It takes a row of children.** A string covers the common case; past
    that, any widgets you pass become the tag's content, laid out in the
    row the badge already is::

        Tag(Icon("check"), Text("Done"), tone="success")

    The rule is positional and simple: a leading string is the label, and
    every other positional must be a widget. The slots the design names —
    ``dot``, ``icon``, ``avatar``, ``flag`` (leading) and ``arrow``,
    ``on_dismiss`` (trailing) — are keywords rather than children, because
    the CSS places them by class and their order is not the caller's to
    choose.

    With an ``icon`` and nothing else it becomes the design's icon-only
    badge — a fixed square — without a separate argument for it.

    ``label`` may be dynamic and is set with ``textContent``, never
    ``innerHTML``.
    """

    widget_type = "Tag"

    def __init__(
        self,
        *content: Any,
        tone: str = "neutral",
        size: str = "md",
        fill: str = "subtle",
        dot: bool = False,
        icon: str | None = None,
        avatar: str | None = None,
        flag: str | None = None,
        arrow: bool = False,
        on_dismiss: Callable | None = None,
        key: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, **kwargs)
        self.label: Any = None
        rest = list(content)
        if rest and isinstance(rest[0], (str, Binding)):
            self.label = rest.pop(0)
        self.content = rest
        self.tone = tone
        self.size = size
        self.fill = fill
        self.dot = dot
        self.icon = icon
        self.avatar = avatar
        self.flag = flag
        self.arrow = arrow
        self.on_dismiss = on_dismiss

    def children(self) -> list[WidgetChild]:
        return list(self.content)

    def props(self) -> dict[str, Any]:
        return {
            "label": self.label,
            "tone": self.tone,
            "size": self.size,
            "fill": self.fill,
            "dot": self.dot,
            "icon": self.icon,
            "avatar": self.avatar,
            "flag": self.flag,
            "arrow": self.arrow,
        }


class _PresetTag(Tag):
    """Base for the shipped tags. Subclasses set ``preset`` only."""

    #: Overridden by each subclass; merged UNDER the caller's arguments, so a
    #: preset never wins an argument the caller passed explicitly.
    preset: dict[str, Any] = {}

    def __init__(self, *content: Any, **kwargs: Any):
        merged = dict(self.preset)
        merged.update(kwargs)
        super().__init__(*content, **merged)


class FilledTag(_PresetTag):
    """The solid treatment — ``fill="filled"``.

        FilledTag("Fix now", tone="critical")

    Defined for the five tones in :data:`TAG_FILLED_TONES`; any other tone
    is an error rather than a silent fallback.
    """

    widget_type = "Tag"
    preset = TAG_PRESETS["FilledTag"]


class OutlineTag(_PresetTag):
    """A bordered tag on no background — ``fill="outline"``.

        OutlineTag("Draft")

    Works for every tone: the border is derived from the tone's own text
    colour where the design does not name one.
    """

    widget_type = "Tag"
    preset = TAG_PRESETS["OutlineTag"]


class Pill(BaseWidget):
    """A rounded, selectable tag — the design's filter pill.

        Pill("vip", selected=self.has_vip, on_click=self.toggle)
        Pill("Drive", on_remove=self.clear)          # carries a ✕

    **A BUTTON, not a :class:`Chip`.** The design builds this out of
    ``btn--tertiary btn--rounded`` (search.html's ``pill()``), so it
    inherits the button system's own hover, active, disabled and focus
    treatment rather than carrying a second set that would drift from it.
    ``Chip`` is the other thing: a label that may be dismissable, styled as
    its own object.

    ``selected`` marks it with ``data-active`` — the same attribute the
    design's own demos use to show the state — so a pill in a filter row
    reads as pressed rather than merely coloured.

    ``size`` is ``"sm"`` (the design's default for these) or ``"md"``.
    """

    widget_type = "Pill"

    def __init__(
        self,
        label: str | Binding,
        *,
        selected: bool | Binding = False,
        on_click: Callable | None = None,
        on_remove: Callable | None = None,
        size: Literal["sm", "md"] = "sm",
        key: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, **kwargs)
        self.label = label
        self.selected = selected
        self.on_click = on_click
        self.on_remove = on_remove
        self.size = size

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {"label": self.label, "selected": self.selected}
        if self.size != "sm":
            p["size"] = self.size
        return p


class Chip(BaseWidget):
    """A compact tag / pill — Flutter's ``Chip``. ``on_click`` makes it tappable,
    ``on_delete`` adds a ✕ that removes it, ``selected`` styles it as active::

        Chip("Design")
        Chip("Filter", on_click=self.toggle, selected=self.active)
        Chip("react", on_delete=self.remove)

    The label may be dynamic and is set with ``textContent`` — never
    ``innerHTML``.
    """

    widget_type = "Chip"

    def __init__(
        self,
        label: str | Binding,
        *,
        on_click: Callable | None = None,
        on_delete: Callable | None = None,
        selected: bool | Binding = False,
        key: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, **kwargs)
        self.label = label
        self.on_click = on_click
        self.on_delete = on_delete
        self.selected = selected

    def props(self) -> dict[str, Any]:
        return {"label": self.label, "selected": self.selected}
